use crate::context::{CheckDef, CheckResult, Context, Create, LiquidCheck, Severity};
use liquid_ast::{Node, NodeKind, NodeRef, VariableLookup};

pub static BLOCK_ID_USAGE: CheckDef = CheckDef {
    code: "BlockIdUsage",
    name: "Do not rely on `block.id` in if/else/unless/case",
    aliases: &[],
    severity: Severity::Warning,
    recommended: true,
    deprecated: false,
    schema: &[],
    create: Create::Liquid(create),
};

const MESSAGE: &str =
    "The ID is dynamically generated by Shopify and is subject to change. You should avoid relying on a literal value of this ID.";

struct Check;

fn create<'a>(_cx: &mut Context<'a>) -> Option<Box<dyn LiquidCheck<'a> + 'a>> {
    Some(Box::new(Check))
}

fn is_using_block_id(node: &VariableLookup) -> bool {
    node.name.as_deref() == Some("block")
        && matches!(node.lookups.first(), Some(Node::String(s)) if s.value == "id")
}

impl<'a> LiquidCheck<'a> for Check {
    fn node_mask(&self) -> u64 {
        NodeKind::Comparison.bit() | NodeKind::VariableLookup.bit()
    }

    fn node(
        &mut self,
        node: NodeRef<'a>,
        ancestors: &[NodeRef<'a>],
        cx: &mut Context<'a>,
    ) -> CheckResult {
        match node {
            // BAD: {% if block.id == "123" %}
            NodeRef::Comparison(c) => {
                if c.comparator == "=="
                    && matches!(c.left.as_ref(), Node::VariableLookup(l) if is_using_block_id(l))
                {
                    cx.report(MESSAGE, c.position.start, c.position.end);
                }
            }
            // BAD: {% case block.id %}
            NodeRef::VariableLookup(v) => {
                if matches!(ancestors.last(), Some(NodeRef::LiquidTag(t)) if t.name == "case")
                    && is_using_block_id(v)
                {
                    cx.report(MESSAGE, v.position.start, v.position.end);
                }
            }
            _ => {}
        }
        Ok(())
    }
}
